{
  "name": "Timepix/Medipix 像素探测器",
  "name_en": "Timepix/Medipix pixel detector",
  "manufacturer": "",
  "description": "用于控制 Timepix/Medipix 像素探测器的高层接口，可配置像素阈值、掩膜、测试脉冲和多项 DAC 偏置参数，并执行设备设置、采集启动/停止、数据记录及以太网通信配置，适用于辐射探测、粒子成像和时间相关测量实验。",
  "description_en": "A high-level control interface for a Timepix/Medipix pixel detector. It supports configuring pixel thresholds, masks, test pulses, and multiple DAC bias parameters, as well as device setup, acquisition start/stop, data recording, and Ethernet communication settings for radiation detection, particle imaging, and time-related measurements.",
  "actions": [
    {
      "action_name": "auto-update_timer",
      "description": "更新设备心跳定时器。",
      "description_en": "Update the device heartbeat timer."
    },
    {
      "action_name": "auto-maskPixelsJsonable",
      "description": "获取/设置可 JSON 序列化的像素掩膜配置。",
      "description_en": "Get/set the JSON-serializable pixel mask configuration."
    },
    {
      "action_name": "auto-setupAcquisition",
      "description": "配置探测器数据采集对象。",
      "description_en": "Configure the detector acquisition object."
    },
    {
      "action_name": "auto-setConfigClass",
      "description": "设置设备配置类。",
      "description_en": "Set the device configuration class."
    },
    {
      "action_name": "auto-loadConfig",
      "description": "从配置类加载 DAC 设置。",
      "description_en": "Load DAC settings from the configuration class."
    },
    {
      "action_name": "auto-setupDevice",
      "description": "设置设备采集参数。",
      "description_en": "Set up the device acquisition parameters."
    },
    {
      "action_name": "auto-pauseHeartbeat",
      "description": "暂停设备心跳。",
      "description_en": "Pause the device heartbeat."
    },
    {
      "action_name": "auto-resumeHeartbeat",
      "description": "恢复设备心跳。",
      "description_en": "Resume the device heartbeat."
    },
    {
      "action_name": "auto-devIdToString",
      "description": "将设备 ID 转换为可读字符串。",
      "description_en": "Convert the device ID to a human-readable string."
    },
    {
      "action_name": "auto-setEthernetFilter",
      "description": "设置以太网数据包过滤器。",
      "description_en": "Set the Ethernet packet filter."
    },
    {
      "action_name": "auto-resetPixels",
      "description": "清除像素配置。",
      "description_en": "Clear the pixel configuration."
    },
    {
      "action_name": "auto-pixelThreshold",
      "description": "获取/设置像素阈值矩阵。",
      "description_en": "Get/set the pixel threshold map."
    },
    {
      "action_name": "auto-pixelMask",
      "description": "获取/设置像素掩膜矩阵。",
      "description_en": "Get/set the pixel mask map."
    },
    {
      "action_name": "auto-pixelTest",
      "description": "获取/设置像素测试矩阵。",
      "description_en": "Get/set the pixel test map."
    },
    {
      "action_name": "auto-uploadPixels",
      "description": "将本地像素配置上传到探测器。",
      "description_en": "Upload the local pixel configuration to the detector."
    },
    {
      "action_name": "auto-refreshPixels",
      "description": "从探测器刷新本地像素配置。",
      "description_en": "Refresh the local pixel configuration from the detector."
    },
    {
      "action_name": "auto-start",
      "description": "启动探测器采集。",
      "description_en": "Start detector acquisition."
    },
    {
      "action_name": "auto-stop",
      "description": "停止探测器采集。",
      "description_en": "Stop detector acquisition."
    },
    {
      "action_name": "auto-start_recording",
      "description": "开始将探测器数据记录到指定路径。",
      "description_en": "Start recording detector data to the specified path."
    },
    {
      "action_name": "auto-stop_recording",
      "description": "停止记录探测器数据。",
      "description_en": "Stop recording detector data."
    },
    {
      "action_name": "auto-polarity",
      "description": "获取/设置极性。",
      "description_en": "Get/set the polarity."
    },
    {
      "action_name": "auto-operationMode",
      "description": "获取/设置工作模式。",
      "description_en": "Get/set the operation mode."
    },
    {
      "action_name": "auto-grayCounter",
      "description": "获取/设置 Gray counter 模式。",
      "description_en": "Get/set the gray counter mode."
    },
    {
      "action_name": "auto-testPulse",
      "description": "获取/设置测试脉冲设置。",
      "description_en": "Get/set the test pulse setting."
    },
    {
      "action_name": "auto-superPixel",
      "description": "获取/设置 superpixel 模式。",
      "description_en": "Get/set the superpixel mode."
    },
    {
      "action_name": "auto-timerOverflowControl",
      "description": "获取/设置计时器溢出控制。",
      "description_en": "Get/set the timer overflow control."
    },
    {
      "action_name": "auto-testPulseDigitalAnalog",
      "description": "获取/设置测试脉冲数字/模拟选择。",
      "description_en": "Get/set the test pulse digital/analog selection."
    },
    {
      "action_name": "auto-testPulseGeneratorSource",
      "description": "获取/设置测试脉冲发生器源。",
      "description_en": "Get/set the test pulse generator source."
    },
    {
      "action_name": "auto-timeOfArrivalClock",
      "description": "获取/设置到达时间时钟设置。",
      "description_en": "Get/set the time-of-arrival clock setting."
    },
    {
      "action_name": "auto-Ibias_Preamp_ON",
      "description": "获取/设置前置放大器开启偏置电流。",
      "description_en": "Get/set the preamplifier ON bias current."
    },
    {
      "action_name": "auto-Ibias_Preamp_OFF",
      "description": "获取/设置前置放大器关闭偏置电流。",
      "description_en": "Get/set the preamplifier OFF bias current."
    },
    {
      "action_name": "auto-VPreamp_NCAS",
      "description": "获取/设置前置放大器 NCAS 电压。",
      "description_en": "Get/set the preamplifier NCAS voltage."
    },
    {
      "action_name": "auto-Ibias_Ikrum",
      "description": "获取/设置 Ikrum 偏置电流。",
      "description_en": "Get/set the Ikrum bias current."
    },
    {
      "action_name": "auto-Vfbk",
      "description": "获取/设置反馈电压。",
      "description_en": "Get/set the feedback voltage."
    },
    {
      "action_name": "auto-Vthreshold_fine",
      "description": "获取/设置细调阈值电压。",
      "description_en": "Get/set the fine threshold voltage."
    },
    {
      "action_name": "auto-Vthreshold_coarse",
      "description": "获取/设置粗调阈值电压。",
      "description_en": "Get/set the coarse threshold voltage."
    },
    {
      "action_name": "auto-Ibias_DiscS1_ON",
      "description": "获取/设置鉴别器 S1 开启偏置电流。",
      "description_en": "Get/set the discriminator S1 ON bias current."
    },
    {
      "action_name": "auto-Ibias_DiscS1_OFF",
      "description": "获取/设置鉴别器 S1 关闭偏置电流。",
      "description_en": "Get/set the discriminator S1 OFF bias current."
    },
    {
      "action_name": "auto-Ibias_DiscS2_ON",
      "description": "获取/设置鉴别器 S2 开启偏置电流。",
      "description_en": "Get/set the discriminator S2 ON bias current."
    },
    {
      "action_name": "auto-Ibias_DiscS2_OFF",
      "description": "获取/设置鉴别器 S2 关闭偏置电流。",
      "description_en": "Get/set the discriminator S2 OFF bias current."
    },
    {
      "action_name": "auto-Ibias_PixelDAC",
      "description": "获取/设置像素 DAC 偏置电流。",
      "description_en": "Get/set the pixel DAC bias current."
    },
    {
      "action_name": "auto-Ibias_TPbufferIn",
      "description": "获取/设置测试脉冲缓冲输入偏置电流。",
      "description_en": "Get/set the test pulse buffer input bias current."
    },
    {
      "action_name": "auto-Ibias_TPbufferOut",
      "description": "获取/设置测试脉冲缓冲输出偏置电流。",
      "description_en": "Get/set the test pulse buffer output bias current."
    },
    {
      "action_name": "auto-VTP_coarse",
      "description": "获取/设置粗调测试脉冲电压。",
      "description_en": "Get/set the coarse test pulse voltage."
    },
    {
      "action_name": "auto-VTP_fine",
      "description": "获取/设置细调测试脉冲电压。",
      "description_en": "Get/set the fine test pulse voltage."
    },
    {
      "action_name": "auto-setDac",
      "description": "按代码设置 DAC 参数。",
      "description_en": "Set a DAC parameter by code."
    }
  ],
  "tag_hints": [
    "Timepix",
    "Medipix",
    "pixel detector",
    "radiation detection",
    "per-pixel threshold and mask",
    "detector DAC tuning",
    "time-of-arrival measurement",
    "Ethernet data acquisition"
  ]
}

